#!/usr/bin/env python3
"""Independent Fraction review of the two equivalent two-hyperplane/cubic component sources.
Arithmetic primitives reused from the dependent-source independent reviewer;
no producer, SymPy, or producer Jacobi/rank helper is imported.
"""
from fractions import Fraction as F
from itertools import combinations,combinations_with_replacement,product
from pathlib import Path
import ast,hashlib,json,resource,sys,time

resource.setrlimit(resource.RLIMIT_CPU,(55,56))
resource.setrlimit(resource.RLIMIT_AS,(1536*1024**2,1536*1024**2))
started=time.monotonic();ROOT=Path.cwd();N=20
pairs=list(combinations(range(5),2))
def term(a,*inds):
    m=[0]*N
    for i in inds:m[i]+=1
    return {tuple(m):F(a)} if a else {}
def add(*ps):
    r={}
    for p in ps:
        for m,a in p.items():r[m]=r.get(m,F(0))+a
    return {m:a for m,a in r.items() if a}
def scale(p,a):return {m:a*b for m,b in p.items() if a*b}
def mul(p,q):
    r={}
    for m,a in p.items():
        for n,b in q.items():
            k=tuple(x+y for x,y in zip(m,n));r[k]=r.get(k,F(0))+a*b
    return {m:a for m,a in r.items() if a}
def der(p,i):
    r={}
    for m,a in p.items():
        if m[i]:
            k=list(m);k[i]-=1;r[tuple(k)]=a*m[i]
    return r
def tensor(data):
    r={}
    for (i,j),p in data.items():r[i,j]=p;r[j,i]=scale(p,-1)
    return r
def projective_jacobi(A):
    triples={}
    for i,j,k in combinations(range(5),3):
        triples[i,j,k]=add(*(mul(A.get((a,l),{}),der(A.get((b,c),{}),l))
                for a,b,c in [(i,j,k),(j,k,i),(k,i,j)] for l in range(5)))
    return {inds:add(*(scale(mul(term(1,inds[k]),triples[inds[:k]+inds[k+1:]]),(-1)**k)
              for k in range(4))) for inds in combinations(range(5),4)}
def monomials(degree):
    out=[]
    for factors in combinations_with_replacement(range(5),degree):
        m=[0]*5
        for i in factors:m[i]+=1
        out.append(tuple(m))
    return out
mon2=monomials(2);mon4=monomials(4)
column_basis=[(ij,m) for ij in pairs for m in mon2]
row_basis=[(inds,m) for inds in combinations(range(5),4) for m in mon4]
row_index={v:i for i,v in enumerate(row_basis)}
def bivector_vector(A):return [A.get(ij,{}).get(m+(0,)*(N-5),F(0)) for ij,m in column_basis]
def jacobi_vector(A):
    J=projective_jacobi(A)
    return [J[inds].get(m+(0,)*(N-5),F(0)) for inds,m in row_basis]
def parse_polynomial(text):
    names=dict(zip(('h','x1','x2','x3','x4')+tuple('n'+str(i) for i in range(14)),range(19)))
    names.update(x=1,u=2,v=3,w=4)
    def walk(n):
        if isinstance(n,ast.Constant) and isinstance(n.value,int):return term(n.value)
        if isinstance(n,ast.Name) and n.id in names:return term(1,names[n.id])
        if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.USub):return scale(walk(n.operand),-1)
        if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.UAdd):return walk(n.operand)
        if isinstance(n,ast.BinOp):
            if isinstance(n.op,ast.Add):return add(walk(n.left),walk(n.right))
            if isinstance(n.op,ast.Sub):return add(walk(n.left),scale(walk(n.right),-1))
            if isinstance(n.op,ast.Mult):return mul(walk(n.left),walk(n.right))
            if isinstance(n.op,ast.Pow) and isinstance(n.right,ast.Constant) and isinstance(n.right.value,int) and n.right.value>=0:
                r=term(1)
                for _ in range(n.right.value):r=mul(r,walk(n.left))
                return r
            if isinstance(n.op,ast.Div) and isinstance(n.right,ast.Constant) and isinstance(n.right.value,int):return scale(walk(n.left),F(1,n.right.value))
        raise ValueError(ast.dump(n))
    return walk(ast.parse(text,mode='eval').body)
def parse_tensor(data):
    return tensor({tuple(ast.literal_eval(ij)):parse_polynomial(p) for ij,p in data.items()})

def modular_minor(A,prime=1000003):
    original=[[int(a.numerator)*pow(int(a.denominator),-1,prime)%prime if isinstance(a,F) else a%prime
               for a in row] for row in A]
    B=[r[:] for r in original];nr=len(B);nc=len(B[0]);labels=list(range(nr));rows=[];cols=[];rank=0
    for j in range(nc):
        k=next((i for i in range(rank,nr) if B[i][j]),None)
        if k is None:continue
        B[rank],B[k]=B[k],B[rank];labels[rank],labels[k]=labels[k],labels[rank]
        rows.append(labels[rank]);cols.append(j)
        inv=pow(B[rank][j],-1,prime);B[rank]=[a*inv%prime for a in B[rank]]
        for i in range(rank+1,nr):
            a=B[i][j]
            if a:B[i]=[(x-a*y)%prime for x,y in zip(B[i],B[rank])]
        rank+=1
    minor=[[original[i][j] for j in cols] for i in rows];det=1
    for j in range(rank):
        k=next(i for i in range(j,rank) if minor[i][j])
        if k!=j:minor[k],minor[j]=minor[j],minor[k];det=-det
        a=minor[j][j];det=det*a%prime;inv=pow(a,-1,prime)
        for i in range(j+1,rank):
            b=minor[i][j]*inv%prime
            if b:minor[i]=[(x-b*y)%prime for x,y in zip(minor[i],minor[j])]
    assert det
    return {'prime':prime,'rank_mod_prime':rank,'minor_rows':rows,'minor_columns':cols,'minor_determinant_mod_prime':det}

def strict_jacobi(A):
    return [add(*(mul(A.get((a,l),{}),der(A.get((b,c),{}),l))
            for a,b,c in [(i,j,k),(j,k,i),(k,i,j)] for l in range(5)))
            for i,j,k in combinations(range(5),3)]

def specialize(p, values):
    out={}
    for m,a in p.items():
        mm=list(m)
        for i,value in values.items():a*=value**mm[i];mm[i]=0
        out[tuple(mm)]=out.get(tuple(mm),F(0))+a
    return {m:a for m,a in out.items() if a}

def homogeneous_linear(p):
    out={}
    for m,a in p.items():
        assert sum(m)<=1
        mm=list(m);mm[0]+=1-sum(m);out[tuple(mm)]=a
    return out

def rational_relations(A):
    B=[[F(a) for a in row] for row in A];nr=len(B);nc=len(B[0]);pivots=[];rank=0
    for j in range(nc):
        k=next((i for i in range(rank,nr) if B[i][j]),None)
        if k is None:continue
        B[rank],B[k]=B[k],B[rank];a=B[rank][j];B[rank]=[v/a for v in B[rank]]
        for i in range(nr):
            a=B[i][j]
            if i!=rank and a:B[i]=[x-a*y for x,y in zip(B[i],B[rank])]
        pivots.append(j);rank+=1
    free=[j for j in range(nc) if j not in pivots];relations=[]
    for j in free:
        rel=[F(0)]*nc;rel[j]=1
        for i,k in enumerate(pivots):rel[k]=-B[i][j]
        assert all(sum(x*y for x,y in zip(row,rel))==0 for row in A)
        relations.append(rel)
    return {'rank':rank,'free_columns':free,'independent_kernel_relations':[[str(a) for a in rel] for rel in relations]}

def matrix_hash(A):
    # Match the frozen producer's SymPy-string matrix serialization exactly.
    return hashlib.sha256(json.dumps([[str(a) for a in row] for row in A]).encode()).hexdigest()

def compose(p,substitutions):
    out={}
    for m,a in p.items():
        value=term(a)
        for i,power in enumerate(m):
            factor=substitutions.get(i,term(1,i))
            for _ in range(power):value=mul(value,factor)
        out=add(out,value)
    return out

def homogenize(p,degree):
    out={}
    for m,a in p.items():
        assert m[0]==0 and sum(m[:5])<=degree
        mm=list(m);mm[0]=degree-sum(m[:5]);out[tuple(mm)]=a
    return out

def decode(data):return tensor({tuple(map(int,ij.split(','))):parse_polynomial(p) for ij,p in data.items()})

def pfaffian(A):
    return add(mul(A.get((1,2),{}),A.get((3,4),{})),scale(mul(A.get((1,3),{}),A.get((2,4),{})),-1),mul(A.get((1,4),{}),A.get((2,3),{})))

report_path=Path('reports/CLASSIFICATION_TWO_HYPERPLANES_CUBIC_NILPOTENT_COMPONENTS_20261107.json')
report=json.loads(report_path.read_text());data=report['component_input']
source_path=Path(data['source_report']);source=json.loads(source_path.read_text())
assert hashlib.sha256(source_path.read_bytes()).hexdigest()==report['source_report_sha256']
records=[];points={}
for name in ['j21_hx_h_p1','j21_hx_h_pm1']:
    begun=time.monotonic();spec=next(v for v in data['branches'] if v['name']==name)
    saved=next(v for v in report['branches'] if v['name']==name)
    assert saved['full_source_specification']==spec
    chart=source['cases'][spec['chart_index']];assert chart['case']=='j21_hx_h'
    substitution={5+int(k[1:]):parse_polynomial(v) for k,v in spec['substitution'].items()}
    base=tensor({tuple(map(int,k.split(','))):compose(parse_polynomial(v),substitution) for k,v in chart['brackets'].items()})
    assert all(not compose(parse_polynomial(v),substitution) for v in chart['remaining_coefficient_equations'])
    assert all(not p for p in strict_jacobi(base))
    common=F(saved['integer_scale']);Pgen=tensor({ij:scale(base.get(ij,{}),common) for ij in pairs})
    assert {ij:v for ij,v in Pgen.items() if v}==decode(saved['universal_brackets'])
    pf=pfaffian(base)
    assert pf==mul(term(1,1),compose(parse_polynomial(chart['actual_cubic']),substitution))
    assert specialize(pf,{0:F(1)})==parse_polynomial(saved['universal_pfaffian'])
    params=[5+int(k[1:]) for k in spec['free_parameters']];assert len(params)==5
    values={5+int(k[1:]):F(v) for k,v in spec['witness'].items()}
    assert set(values)==set(params) and all(v==0 for v in values.values())
    P=tensor({ij:specialize(Pgen.get(ij,{}),values) for ij in pairs})
    assert {ij:v for ij,v in P.items() if v}==decode(saved['witness_brackets']);points[name]=P
    directions=[tensor({ij:specialize(der(Pgen.get(ij,{}),p),values) for ij in pairs}) for p in params]
    D=[[0]*150 for _ in row_basis]
    for col,(ij,m) in enumerate(column_basis):
        variation=tensor({ij:{m+(0,)*(N-5):F(1)}})
        mixed=tensor({kl:add(P.get(kl,{}),mul(term(1,19),variation.get(kl,{}))) for kl in pairs})
        for inds,p in projective_jacobi(mixed).items():
            for exponent,a in p.items():
                if exponent[19]==1:
                    assert a.denominator==1 and not any(exponent[5:19])
                    D[row_index[inds,exponent[:5]]][col]=int(a)
    vectors=[]
    for i,j in product(range(5),repeat=2):
        A=tensor({(k,l):add(term(int(l==i),k,j),term(-int(k==i),l,j)) for k,l in pairs})
        vectors.append(bivector_vector(A))
    for i,j in product(range(5),repeat=2):
        A=tensor({(k,l):add(scale(mul(term(1,j),der(P.get((k,l),{}),i)),-1),
            scale(P.get((j,l),{}),int(k==i)),scale(P.get((k,j),{}),int(l==i))) for k,l in pairs})
        vectors.append(bivector_vector(A))
    vectors.append(bivector_vector(P));vectors.extend(map(bivector_vector,directions))
    Fmatrix=list(map(list,zip(*vectors)))
    for row in D:
        nz=[(j,a) for j,a in enumerate(row) if a]
        assert all(sum(a*v[j] for j,a in nz)==0 for v in vectors)
    matrices={'Jacobi':D,'vertical':[r[:25] for r in Fmatrix],'orbit_scale':[r[:51] for r in Fmatrix],'family':Fmatrix}
    certs={k:modular_minor(v) for k,v in matrices.items()};ranks={k:v['rank_mod_prime'] for k,v in certs.items()}
    assert ranks==saved['matrix_ranks_mod_prime'],(name,ranks,saved['matrix_ranks_mod_prime'])
    assert ranks['Jacobi']==103 and ranks['vertical']==24 and ranks['family']==47
    assert ranks['Jacobi']+ranks['family']==150
    records.append({'source':name,'full_five_parameters':spec['free_parameters'],'all_source_substitutions_and_Jacobi_exact':True,
        'universal_actual_Pfaffian_exact':True,'witness_and_source_directions_reconstructed':True,
        'full350_by150_D_reconstructed':True,'exact_D_times_all_actual_directions_zero':True,
        'QQ_ranks_by_exact_kernel_sandwich':ranks,'rank_lower_certificates':certs,
        'projective_tangent_dimension':22,'witness_orbit_dimension':ranks['orbit_scale']-25,
        'generic_orbit_dimension_not_determined':True,'smooth_full_component_dimension':22,
        'seconds':time.monotonic()-begun})
    print(json.dumps({k:records[-1][k] for k in ['source','QQ_ranks_by_exact_kernel_sandwich','seconds']}),flush=True)

# Actual PGL transformation (h',x',u',v',w')=(x,h,u,-v,w-v), followed by h'-Casimir gauge.
T=[[0]*5 for _ in range(5)]
T[0][1]=T[1][0]=T[2][2]=T[4][4]=1;T[3][3]=T[4][3]=-1
inverse={0:term(1,1),1:term(1,0),2:term(1,2),3:term(-1,3),4:add(term(1,4),term(-1,3))}
P=points['j21_hx_h_p1'];Q={}
for i,j in pairs:
    value=add(*(scale(P.get((u,v),{}),T[i][u]*T[j][v]) for u in range(5) for v in range(5)))
    Q[i,j]=compose(value,inverse);Q[j,i]=scale(Q[i,j],-1)
Y=[{}]
for j in range(1,5):
    value={}
    for m,a in Q[0,j].items():
        assert m[0]>0;e=list(m);e[0]-=1;value[tuple(e)]=a
    Y.append(value)
corrected=tensor({(i,j):add(Q.get((i,j),{}),scale(mul(term(1,i),Y[j]),-1),mul(term(1,j),Y[i])) for i,j in pairs})
assert all(corrected.get(ij,{})==scale(points['j21_hx_h_pm1'].get(ij,{}),F(1,2)) for ij in pairs)
checker=Path(__file__).read_text()
out={'task_id':'E_reduced_nonnormal','all_passed':True,'field':'QQ','method':'Independent Fraction sparse polynomials; no producer/SymPy/legacy engine imports.',
    'input_sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [report_path,source_path]},
    'independent_checker_source':checker,'checker_sha256':hashlib.sha256(checker.encode()).hexdigest(),'branches':records,
    'exact_PGL_and_Casimir_gauge_identifies_two_witnesses':True,'same_unique_smooth_component':True,
    'scope':'Both full five-parameter sources give the same smooth22 component. Witness orbit dimension21 does not determine the generic orbit dimension. Full45 linear reduction and geometric distinctness are separate written dependencies; no global exhaustion.',
    'elapsed_seconds':time.monotonic()-started}
Path(sys.argv[1]).write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({'all_passed':True,'same_component':True,'elapsed_seconds':out['elapsed_seconds']}))
